"""Layer 15 MLP, hidden unit 2440 (component 2440 of layers.15.mlp.down_proj).

This component reads almost entirely one MLP hidden unit (its read vector is dominated
by unit 2440), and that unit is strongly negative at the end of a chat turn. In plain
terms, it:

- goes strongly negative at `<|im_end|>`, the end-of-turn marker: about -15 when the
  turn ends in ordinary text, and about -8 when it ends right after a closing tool tag;
- goes strongly negative at `</think>`, the close of a reasoning block (about -13);
- goes moderately negative at closing tool tags `</tool_call>` and `</tool_response>`
  (about -4), and a little at the opening `<tool_call>` (about -2.5);
- is slightly negative at sentence-opening pronouns and articles ("The", "They", "We", ...);
- is slightly positive after a colon (about +0.9), and after commas, full stops,
  newlines and closing parentheses (about +0.2);
- is zero everywhere else.

The program is a lookup over the newest token (and the token before it, for the
`<|im_end|>` case). It ignores everything else, so it captures the big end-of-turn
dips but not the diffuse, context-dependent wobble of the rest of the activation.
"""

READS = ()

CLOSING_TOOL_TAGS = {"</tool_call>", "</tool_response>"}
PUNCTUATION = {",", ".", "\n", ")"}
SENTENCE_OPENERS = {"The", "They", "We", "It", "This", "These", "In", "A", "I", "He", "She"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token == "<|im_end|>":
        value = -8.0 if previous in CLOSING_TOOL_TAGS else -15.0
    elif token == "</think>":
        value = -13.0
    elif token in CLOSING_TOOL_TAGS:
        value = -4.0
    elif token == "<tool_call>":
        value = -2.5
    elif token == ":":
        value = 0.9
    elif token in PUNCTUATION:
        value = 0.2
    elif token.strip() in SENTENCE_OPENERS:
        value = -0.6
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15 MLP unit 2449 (the down_proj component 2449), as a reading of relational phrases.

What it does: this component is almost entirely one MLP hidden unit. Its activation is
large mainly on the first few words after "between" (and related words such as
"relationship", "difference", "correlation", "interaction", "association"), the words that
name the two things being related. The sign follows the number of the thing named:
plural or paired items ("between the two groups", "between teachers") push it positive;
a singular item ("between the sensor and") pushes it negative; function words
("the", "a", "(") push it slightly negative. Elsewhere it is near zero, with no simple
rule that predicts its spikes.

The program tracks how many words have passed since the last relational word in the same
document, and scores the first WINDOW words after it by the number of the word.
"""

import inflect

READS = ()

RELATION_WORDS = {
    "between", "relationship", "relation", "correlation", "difference",
    "interaction", "association", "comparison",
}
WINDOW = 3
PLURAL_WORDS = {"two", "both", "three", "several", "many", "they", "them", "these", "those"}
FUNCTION_WORDS = {
    "", "the", "a", "an", "of", "(", '"', "'", "and", "or", "to", "in", "on", "for", "with",
    "its", "their", "our", "his", "her",
}
PHRASE_END = set(".,;:!?\n")
PLURAL_VALUE = 2.2
SINGULAR_VALUE = -1.9
FUNCTION_VALUE = -0.5

_inflect = inflect.engine()
_plural_cache = {}


def is_plural(word):
    """A plural or paired word: 'two', 'both', or an English noun that inflect reads as plural."""
    if word not in _plural_cache:
        _plural_cache[word] = word in PLURAL_WORDS or (
            len(word) > 3 and _inflect.singular_noun(word) is not False
        )
    return _plural_cache[word]


def step(carry, prefix, upstream):
    # carry: (words since the last relation word, or None; the document id it belongs to)
    since, doc = carry if carry is not None else (None, None)
    if prefix.document_ids[-1] != doc:
        since = None
    doc = prefix.document_ids[-1]
    word = prefix.token_strings[-1].strip().lower()

    distance = None if since is None else since + 1
    value = 0.0
    if distance is not None and distance <= WINDOW:
        if word in FUNCTION_WORDS:
            value = FUNCTION_VALUE
        elif is_plural(word):
            value = PLURAL_VALUE
        else:
            value = SINGULAR_VALUE

    if word in RELATION_WORDS:
        since = 0
    elif distance is not None:
        since = None if word in PHRASE_END else distance
    return (since, doc), value

"""Expenditure detector for layers.15 MLP unit 2454.

The component is one hidden unit of layer 15's MLP, read into the residual stream. Its
activation is negative where the text is spending or using up a resource -- time, money,
effort, energy, memory -- and it is most negative on the spending verb itself ("spend",
"waste") and on "cost" / "takes" / "effort". Numbers that follow such words (amounts of
money, durations) are mildly negative too. Almost everywhere else it is near zero.

This program predicts the activation from the current token and the few tokens before it:

  spending verbs (spend, spent, waste, ...)            -> -5
  cost / effort / take words (cost, expensive, takes)  -> -2.5
  resource nouns (time, hours, money, ...)             -> -1.3
  weaker resource nouns (memory, energy, years, ...)   -> -0.7
  'time' right after 'this', 'every', 'next', ...      -> 0 (as in 'every time')
  a number within 8 tokens of a resource or money word -> -0.6

Chinese and Russian words for the same ideas (花, 耗费, 成本, 时间, 钱; время, сил) count too.
"""

import re

READS = ()

SPEND = {"spend", "spends", "spending", "spent", "waste", "wasted", "wasting", "付出", "耗费"}
EXPENSE = {
    "cost", "costs", "costly", "expense", "expensive", "effort", "take", "takes", "took",
    "taking", "worth", "成本", "费用", "精力", "花", "消耗", "время", "сил",
}
RESOURCE = {
    "time", "times", "hours", "hour", "minutes", "minute", "money", "resources", "labor",
    "pay", "时间", "钱", "资源",
}
WEAK_RESOURCE = {
    "memory", "storage", "space", "energy", "bandwidth", "budget", "fee", "dollars",
    "million", "billion", "years", "weeks", "seconds", "afford", "save", "saving", "lose",
    "lost",
}
MONEY = {"$", "€", "£", "price", "dollars"}
NOT_A_QUANTITY = {"this", "each", "every", "next", "first", "last", "one", "any"}
WINDOW = 8


def step(carry, prefix, upstream):
    recent = [s.strip().lower() for s in prefix.token_strings[-WINDOW - 1:]]
    word = recent[-1]
    before = recent[-2] if len(recent) > 1 else ""
    if word in SPEND:
        return carry, -5.0
    if word in EXPENSE:
        return carry, -2.5
    if word in RESOURCE and not (word == "time" and before in NOT_A_QUANTITY):
        return carry, -1.3
    if word in WEAK_RESOURCE:
        return carry, -0.7
    if re.fullmatch(r"\d", word):
        if any(t in SPEND | EXPENSE | RESOURCE | WEAK_RESOURCE | MONEY for t in recent[:-1]):
            return carry, -0.6
    return carry, 0.0

"""Copula detector: layers.15.mlp.down_proj, component 2472.

What it does: this component is a copula detector. It is large on forms of "be" (is, was, are, were, been, being, 'm, 're), the verb that joins a
subject to what follows it. It is largest when a passive participle or a description is
the likely next word: "the church [was] demolished", "it [has been] used", "a structure
[is] called". It is weaker after the existential subjects "there", "what", "here"
("there [is]"), a little positive on the same verb-slot words in other languages (ser,
è, sono, ist), and on adverbs and negation that sit where the verb would go ("not",
"often", "also"). The chat role word "assistant" pushes it strongly negative. Everything
else is about zero.

Why these numbers: they are the average activation of each class in sampled text,
rounded. The program reads only the current token and the one before it, within the same
document.
"""

# Mean activation of each English be-form, in the component's units.
COPULA = {
    "be": 5.8, "been": 6.8, "being": 5.2, "was": 6.4, "were": 5.8,
    "is": 4.7, "are": 4.8, "am": 3.0, "'m": 3.0, "’m": 3.0, "'re": 3.8, "’re": 3.8,
}
# Be-forms after these words are usually followed by a participle: "can be", "has been".
AUXILIARY = {
    "can", "may", "will", "should", "must", "shall", "could", "would", "might",
    "has", "have", "had", "been", "be", "not", "also",
}
# Existential or demonstrative subjects: "there is", "what is", "here are".
EXISTENTIAL = {"there", "what", "here"}
# Copulas in other languages, read as a weaker version of the English ones.
FOREIGN_COPULA = {
    "ser", "è", "sono", "era", "est", "essere", "ist", "es",
    "sont", "été", "être", "são", "fue",
}
# Adverbs and negation that sit between a subject and its verb.
VERB_SLOT_ADVERB = {
    "not": 1.3, "also": 1.0, "often": 3.5, "usually": 2.5, "always": 1.4,
    "typically": 2.0, "sometimes": 1.3,
}

READS = ()


def step(carry, prefix, upstream):
    """Activation at the newest token: its class, and the previous token if it is in the
    same document."""
    word = prefix.token_strings[-1].strip().lower()
    docs = prefix.document_ids
    same_document = len(docs) > 1 and docs[-2] == docs[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_document else ""
    if word == "assistant":
        value = -3.5
    elif word in VERB_SLOT_ADVERB:
        value = VERB_SLOT_ADVERB[word]
    elif word in FOREIGN_COPULA:
        value = 2.5
    elif word in COPULA:
        value = COPULA[word]
        if prev in AUXILIARY:
            value = 6.2
        if prev in EXISTENTIAL:
            value = 2.0
    else:
        value = 0.0
    return carry, float(value)

"""Calculation-step detector: the "=" (or ≈, ⇒, →) that ends a numeric or algebraic step.

The component is quiet on most text. It switches on where a calculation is written out,
such as "64−32−12−1 =", "(9+3+2)/2 =" or "sqrt(25−1)≈", most strongly at the sign that
closes the step, where the next token is its result. It also rises weakly on the numbers
and closing brackets inside such a step. Its strength grows with the product of how many
operator signs and how many numbers sit in the last few tokens of the same document.
After a bare variable or in code ("x = 3", "int i = 0") it stays near zero.
"""

READS = ()

RELATIONS = {"=", "≈", "⇒", "→", "≠", ")=", "=-", "&="}
CLOSERS = {")", "²", "³", "%", "]"}
OPERATORS = set("+-−*/^×÷=≈⇒→")
WINDOW = 8


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    doc = prefix.document_ids
    cur = toks[-1].strip()
    lo = len(toks) - 1
    while lo > 0 and len(toks) - lo < WINDOW and doc[lo - 1] == doc[-1]:
        lo -= 1
    window = toks[lo:]
    n_ops = sum(1 for t in window if set(t) & OPERATORS)
    n_nums = sum(1 for t in window if any(c.isdigit() for c in t))
    calc = n_ops * n_nums
    if cur in RELATIONS:
        return carry, max(0.0, 2.0 * calc - 4.0)
    if cur in CLOSERS:
        return carry, max(0.0, 0.8 * calc - 1.0)
    if cur.isdigit():
        return carry, max(0.0, 0.3 * calc - 1.0)
    return carry, 0.0

"""Contrast and negation markers, layer 15 MLP down_proj component 2476.

The component fires on the word that sets up a contrast, exclusion or negation,
as in "rather than", "instead of", "as opposed to", "without", "X, not Y", "X, but Y".
It is strongest on the words "without", "rather", "instead" and their foreign
equivalents; it is moderate on "not", "no", "never", "but", "than" and similar; it
is boosted when the marker follows a comma or a conjunction, and suppressed after
a hedge ("if", "perhaps", "I'm not"). The completing word of a fixed contrast
phrase ("of" in "instead of", "to" in "opposed to", "than" in "rather than")
fires strongly. Everything else is predicted as 0.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

STRONG = {"without", "rather", "instead", "sans", "ohne", "без", "opposed", "lieu", "regardless"}
MODERATE = {
    "not", "no", "never", "nothing", "none", "neither", "nor", "non", "cannot",
    "n't", "'t", "’t", "but", "however", "yet", "although", "though", "despite",
    "unless", "except", "than", "whereas", "不", "没", "没有", "但", "但是", "不能",
}
COMPLETERS = {("of", "instead"), ("of", "lieu"), ("to", "opposed"), ("than", "rather")}
BEFORE_CONTRAST = {",", "，", "、", ";", "and", "but", "or", "rather", "instead"}
HEDGES = {"if", "perhaps", "probably", "maybe", "could", "'m", "’m"}


def step(carry, prefix, upstream: Mapping):
    """Activation at the newest token: a contrast or negation marker's strength."""
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if (prev, word) in COMPLETERS:
        return carry, 4.0
    if word in STRONG:
        value = 3.0
    elif word in MODERATE:
        value = 0.9
    else:
        return carry, 0.0
    if prev in BEFORE_CONTRAST:
        value += 1.0
    if prev in HEDGES:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 2483 (this component's activation) as a word-class guess.

The component is almost exactly one MLP hidden unit: silu(gate) * up, times a
constant. Its sign is set by the up projection, which follows a residual direction
that tracks constructive versus error- or harm-laden text. That direction is not a
per-word property, so word lists explain very little. This program only states
what a few word classes do on average, measured on training text:

- avoidance and harm words ("prevent", "avoid", "against", "except", "bad", "too",
  "negative", "nothing", "never", "any") push the unit negative, most for "prevent"
  and "avoid";
- possessive determiners and "than" ("his", "their", "its", "her", "than") push it
  positive;
- every other token sits near the unit's typical mean.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

AVOIDANCE = {
    "prevent", "avoid", "against", "except", "bad", "too", "negative", "nothing", "never", "any",
}
POSSESSIVE = {"his", "her", "its", "their", "my", "our", "your", "than", "beyond"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    if word in AVOIDANCE:
        value = -0.6
    elif word in POSSESSIVE:
        value = 0.3
    else:
        value = 0.08
    return carry, value

"""Layer-15 MLP unit 2495 (through its rank-one piece): a break inside a noun phrase detector.

It fires on a token that breaks the line or inserts a loose space or quote mark, when that token
comes straight after a determiner ("the", "a", "an", "its", "such" ...). A noun has to follow a
determiner, so a line break or loose space there is an unexpected interruption. After a
preposition it fires more weakly; after an ordinary word, a bare space or quote fires weakly and a
line break hardly at all; after punctuation, code or non-words it stays near zero. Ordinary
tokens (words, digits, punctuation) do not fire.
"""
import regex

READS = ()

DETERMINERS = {
    " the", " a", " an", " its", " this", " that", " such", " any", " other", " his", " her",
    " their", " our", " my", " your", " these", " those", " some", " each", " every",
}
PREPOSITIONS = {
    " of", " in", " for", " to", " with", " and", " or", " by", " from", " on", " at", " as",
    " into", " than", " about", " between", " under", " over",
}
QUOTES = {' "', " '", " “", " ”", " ‘", " ’", " «", " »", " `", " ``"}


def break_kind(token):
    """'newline' for a line break, 'space' for a bare space, 'quote' for a quote mark, else None."""
    if "\n" in token or token == "\\n":
        return "newline"
    if token.strip() == "" and token != "":
        return "space"
    if token in QUOTES:
        return "quote"
    return None


def step(carry, prefix, upstream):
    kind = break_kind(prefix.token_strings[-1])
    if kind is None or len(prefix.token_strings) < 2:
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = prefix.token_strings[-2]
    if before in DETERMINERS:
        return carry, 4.5
    if before in PREPOSITIONS:
        return carry, 2.5 if kind == "newline" else 0.8
    if regex.fullmatch(r"\s?\p{L}+", before):
        return carry, 0.3 if kind == "newline" else 0.9
    return carry, 0.15
